<?php
require_once __DIR__ . '/auth.php';
require_login();
$id = filter_input(INPUT_GET, 'id', FILTER_VALIDATE_INT, ['options' => ['min_range' => 1]]);
if (!$id) { http_response_code(400); exit('ID produk tidak valid.'); }
$stmt = mysqli_prepare($koneksi, 'SELECT id_produk, nama_produk, harga, stok, deskripsi, foto FROM produk WHERE id_produk = ?');
mysqli_stmt_bind_param($stmt, 'i', $id);
mysqli_stmt_execute($stmt);
$produk = mysqli_fetch_assoc(mysqli_stmt_get_result($stmt));
mysqli_stmt_close($stmt);
if (!$produk) { http_response_code(404); exit('Produk tidak ditemukan.'); }
$token = csrf_token();
?>
